      "id": "1830163047256473",
      "title": "Beta Hotfix Patch Notes - v0.103.1",
      "link": "https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1830163047256473",
      "pubDate": "Thu, 16 Apr 2026 03:52:37 GMT",
